import { memo, type ComponentProps, type ReactNode } from "react";
import { ArrowUpRight } from "lucide-react";
import { cn } from "cn";
import { GitHubDark } from "@ridemountainpig/svgl-react";
import { sampleFooterGroups } from "../lib/navigation.shared";
import { Card } from "../components/card";

interface FooterProps extends ComponentProps<"footer"> {
  brand?: string;
  homeHref?: string;
  description?: string;
  groups?: {
    title: string;
    links: {
      label: string;
      href: string;
    }[];
  }[];
  githubHref?: string;
  copyright?: string;
  callout?: {
    title: string;
    description: string;
    label: string;
    href: string;
  };
  action?: ReactNode;
}

// Keep accepting the family prop without forwarding it to the DOM.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
export const FooterMinimal = memo(function FooterMinimal({
  brand = "Hangry UI",
  homeHref = "#home",
  description: _description,
  groups = sampleFooterGroups,
  githubHref = "#github",
  copyright = `© ${new Date().getFullYear()} Hangry UI`,
  callout,
  action,
  className,
  children,
  ...props
}: FooterProps = {}) {
  return (
    <footer
      {...props}
      data-slot="footer"
      data-layout="minimal"
      className={cn("w-full border border-border bg-background text-foreground", className)}
    >
      {callout && (
        <div className="border-b border-border p-6 sm:p-8">
          <Card
            title={callout.title}
            description={callout.description}
            className="max-w-none!"
            footer={
              action ?? (
                <a
                  href={callout.href}
                  className="inline-flex min-h-10 items-center gap-2 text-sm font-medium hover:underline focus-visible:outline-2 focus-visible:outline-ring"
                >
                  {callout.label}
                  <ArrowUpRight size={16} aria-hidden="true" />
                </a>
              )
            }
          />
        </div>
      )}
      <div className={cn("gap-10 p-6 sm:p-8", "flex flex-wrap items-center justify-between")}>
        <div>
          <a
            href={homeHref}
            className="text-xl font-semibold focus-visible:outline-2 focus-visible:outline-ring"
          >
            {brand}
          </a>

          {children}
        </div>
        <div className="flex flex-wrap gap-6">
          {groups.map((group) => (
            <nav key={group.title} aria-label={group.title}>
              <ul className="flex flex-wrap gap-4">
                {group.links.map((link) => (
                  <li key={link.href}>
                    <a
                      href={link.href}
                      className="text-sm text-muted-foreground hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"
                    >
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            </nav>
          ))}
        </div>
      </div>
      <div className="flex flex-wrap items-center justify-between gap-4 border-t border-border px-6 py-4 text-xs text-muted-foreground sm:px-8">
        <span>{copyright}</span>
        {githubHref && (
          <a
            href={githubHref}
            className="inline-flex min-h-9 items-center gap-2 hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring"
          >
            <GitHubDark className="invert dark:invert-0" width={16} height={16} aria-hidden="true" />
            GitHub
          </a>
        )}
      </div>
    </footer>
  );
});

import { memo, type ComponentProps, type ReactNode } from "react";
import { cn } from "cn";

// Legacy content props remain supported for existing consumers.
const cardSizes = {
  sm: "gap-4 px-4 py-4",
  md: "gap-6 px-6 py-6",
} as const;

type CardProps = {
  size?: keyof typeof cardSizes;
  title?: string;
  description?: string;
  footer?: ReactNode;
} & (
  | ({ as?: "article" } & Omit<ComponentProps<"article">, "title">)
  | ({ as: "a" } & Omit<ComponentProps<"a">, "title">)
);

const Card = memo(function Card({
  title,
  description,
  children,
  footer,
  className,
  size = "md",
  ...props
}: CardProps) {
  const hasLegacyContent = Boolean(title || description || footer);
  const classes = cn(
    "group/card flex w-full max-w-sm flex-col rounded-lg surface-raised text-base leading-7",
    "outline-ring focus-visible:outline-[length:var(--focus-ring-width,2px)] focus-visible:outline-offset-[var(--focus-ring-offset,2px)]",
    "[a&]:transition-colors [a&]:duration-[var(--duration-fast,150ms)] [a&]:ease-out [a&]:hover:[--surface-bottom:var(--muted)] motion-reduce:transition-none",
    cardSizes[size],
    className,
  );
  const content = (
    <>
      {(title || description) && (
        <CardHeader>
          {title && <CardTitle>{title}</CardTitle>}
          {description && <CardDescription>{description}</CardDescription>}
        </CardHeader>
      )}
      {hasLegacyContent ? children && <CardContent>{children}</CardContent> : children}
      {footer && <CardFooter>{footer}</CardFooter>}
    </>
  );
  if (props.as === "a") {
    const { as: Tag, ...anchorProps } = props;
    return (
      <Tag data-slot="card" data-size={size} className={classes} {...anchorProps}>
        {content}
      </Tag>
    );
  }
  const { as: Tag = "article", ...articleProps } = props;
  return (
    <Tag data-slot="card" data-size={size} className={classes} {...articleProps}>
      {content}
    </Tag>
  );
});

const CardHeader = memo(function CardHeader({ className, ...props }: ComponentProps<"header">) {
  return (
    <header
      data-slot="card-header"
      className={cn(
        "grid auto-rows-min items-start gap-x-4 gap-y-2 has-[[data-slot=card-action]]:grid-cols-[1fr_auto]",
        className,
      )}
      {...props}
    />
  );
});

const CardTitle = memo(function CardTitle({ className, ...props }: ComponentProps<"h3">) {
  return (
    <h3 data-slot="card-title" className={cn("typography-section-title", className)} {...props} />
  );
});

const CardDescription = memo(function CardDescription({
  className,
  ...props
}: ComponentProps<"p">) {
  return (
    <p
      data-slot="card-description"
      className={cn("col-start-1", "typography-body", className)}
      {...props}
    />
  );
});

const CardAction = memo(function CardAction({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn("col-start-2 row-span-2 row-start-1 self-start justify-self-end", className)}
      {...props}
    />
  );
});

const CardContent = memo(function CardContent({ className, ...props }: ComponentProps<"div">) {
  return <div data-slot="card-content" className={className} {...props} />;
});

const CardFooter = memo(function CardFooter({ className, ...props }: ComponentProps<"footer">) {
  return (
    <footer
      data-slot="card-footer"
      className={cn("flex items-center border-t border-border pt-4", className)}
      {...props}
    />
  );
});

export { Card, CardAction, CardContent, CardDescription, CardFooter, CardHeader, CardTitle };

